def quote(value):
    return '"' + value.replace('\\', '\\\\').replace('"', '\\"').replace('\n', '\\n') + '"'

def header(locale=None):
    lang = locale or ""
    return ["msgid \"\"", "msgstr \"\"", '"Project-Id-Version: PandaWoo Quick 0.2.7\\n"', '"Report-Msgid-Bugs-To: https://github.com/kultur3gmbh/pandawoo-quick/issues\\n"', f'"POT-Creation-Date: {datetime.date.today().isoformat()} 00:00+0000\\n"', f'"PO-Revision-Date: {datetime.date.today().isoformat()} 00:00+0000\\n"', '"Last-Translator: Kultur³ GmbH\\n"', '"Language-Team: ContactPanda\\n"', f'"Language: {lang}\\n"', '"MIME-Version: 1.0\\n"', '"Content-Type: text/plain; charset=UTF-8\\n"', '"Content-Transfer-Encoding: 8bit\\n"', '"Plural-Forms: nplurals=2; plural=(n != 1);\\n"', '"X-Domain: pandawoo-quick\\n"', ""]

refs = {}
for path in sorted(ROOT.rglob("*.php")):
    rel = path.relative_to(ROOT).as_posix()
    for line_no, line in enumerate(path.read_text(encoding="utf-8").splitlines(), 1):
        for match in PATTERN.finditer(line):
            msgid = match.group(1).replace("\\'", "'")
            refs.setdefault(msgid, []).append(f"{rel}:{line_no}")

missing = sorted(set(refs) - set(DE))
extra = sorted(set(DE) - set(refs))
if missing or extra:
    raise SystemExit(f"Translation map mismatch. Missing={missing!r} Extra={extra!r}")

LANG.mkdir(exist_ok=True)
pot = header()
for msgid in sorted(refs):
    pot += ["#: " + " ".join(refs[msgid]), "msgid " + quote(msgid), 'msgstr ""', ""]
(LANG / "pandawoo-quick.pot").write_text("\n".join(pot), encoding="utf-8")

catalogs = {
    "de_DE": DE,
    "de_DE_formal": {**DE, **FORMAL_OVERRIDES},
    "de_CH": {key: value.replace("ß", "ss") for key, value in {**DE, **FORMAL_OVERRIDES}.items()},
}
for locale, translations in catalogs.items():
    po = header(locale)
    for msgid in sorted(refs):
        po += ["#: " + " ".join(refs[msgid]), "msgid " + quote(msgid), "msgstr " + quote(translations[msgid]), ""]
    (LANG / f"pandawoo-quick-{locale}.po").write_text("\n".join(po), encoding="utf-8")

print(f"Generated POT and {len(catalogs)} PO catalogs with {len(refs)} messages.")

